    message: input.required<string>(),
    severity: input<'info' | 'warn' | 'error'>('info'),
  },
  setup: ({ message, severity }) => {
    const visible = signal(true);

    return @{
      <div
        class:alert-visible={visible()}
        class:alert-error={severity() === 'error'}
        style:padding={'1rem'}
        style:opacity={visible() ? '1' : '0'}>
        <p>{message()}</p>
        <button on:click={() => visible.set(false)}>Dismiss</button>
      </div>
    };
  },
  style: `
